prompt:
You are the participant in one small ontology lesson. Use only the supplied input. Do not use tools, access files, or change state. Return only one JSON object matching output_shape. No Markdown or explanation. Arrays of answers are unordered unless the instruction says otherwise.

{
  "experiment": "10",
  "title": "Changed meaning and pinned versions",
  "terms": {
    "semantic change": "Changing what a rule means.",
    "pinned version": "The package an episode uses consistently.",
    "regression": "A required behavior broken by a candidate."
  },
  "instruction": "Compute project-only approval under each version. Candidate v2 has already passed the external release gate. Active episodes remain pinned unless explicitly stopped or migrated. Select the package for each episode. This exercise is not permission to disregard an urgent revocation.",
  "input": {
    "v1": "Project or service approval permits deployment.",
    "v2": "Only service-specific approval permits deployment.",
    "approval": "project",
    "active_episode": {
      "pinned": "v1"
    },
    "accepted_for_new_episodes": "v2"
  },
  "output_shape": {
    "v1_permits": "boolean",
    "v2_permits": "boolean",
    "active_episode_version": "string",
    "new_episode_version": "string"
  }
}
